import json

def transform(grid):
    """
    Transform ARC task task-5885a14a.
    Pattern: For each shape formed by 5s:
    1. Fill row: Next row above shape → fill columns 0 to rightmost-1 with 2s
    2. Shape rows: Preserve 5s, fill interior gaps between leftmost and rightmost 5s with 2s
    3. Base row: Add row below → fill columns from leftmost to rightmost with 5s
    """
    rows = len(grid)
    cols = len(grid[0])
    result = [[0] * cols for _ in range(rows)]

    # Find all 5s and their bounding boxes
    shapes = []
    visited = [[False] * cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 5 and not visited[r][c]:
                # BFS to find connected shape
                stack = [(r, c)]
                visited[r][c] = True
                cols_in_shape = [c]
                while stack:
                    curr_r, curr_c = stack.pop()
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 5 and not visited[nr][nc]:
                            visited[nr][nc] = True
                            stack.append((nr, nc))
                            cols_in_shape.append(nc)
                shapes.append(cols_in_shape)

    # Process each shape
    for cols_in_shape in shapes:
        # Find top row of this shape
        min_c = min(cols_in_shape)
        max_c = max(cols_in_shape)

        # Find all rows in this shape
        shape_rows = set()
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == 5 and c in cols_in_shape:
                    shape_rows.add(r)

        if not shape_rows:
            continue

        min_r, max_r = min(shape_rows), max(shape_rows)

        # Determine which rows belong to this shape
        rows_in_shape = set()
        for r in range(max_r + 1):
            for c in cols_in_shape:
                if grid[r][c] == 5:
                    rows_in_shape.add(r)

        if not rows_in_shape:
            min_r = max_r
            rows_in_shape = set(range(min_r, max_r + 1))

        # Add fill row above (at min_r - 1, but demo uses min_r instead with different treatment)
        # From demo: fill row at row 2 (min_r), base row at row 6 (max_r + 1)
        fill_row_idx = min_r  # Demo shows fill row at same row as shape top
        base_row_idx = max_r + 1

        # Fill row: columns 0 to max_c filled with 2s, but demo shows fill at min_r with 0 to max_c-1
        if fill_row_idx < rows:
            for c in range(max_c):
                result[fill_row_idx][c] = 2

        # Middle rows: preserve 5s, fill interior with 2s
        for r in sorted(rows_in_shape):
            if r in shape_rows:
                for c in range(cols):
                    if grid[r][c] == 5:
                        result[r][c] = 5
                    elif c > min_c and c < max_c:
                        result[r][c] = 2

        # Base row: fill from leftmost to rightmost with 5s
        if base_row_idx < rows:
            for c in range(min_c, max_c + 1):
                result[base_row_idx][c] = 5

    return result

